changeSet.sql:
ALTER TABLE tournament_registrations
    ADD CONSTRAINT ck_tournament_registrations_no_self_partner
    CHECK (partner_player_id IS NULL OR partner_player_id <> player_id);

CREATE OR REPLACE FUNCTION fn_assert_one_entry_per_category() RETURNS trigger LANGUAGE plpgsql AS $fn$ DECLARE conflict_name text; scope_key text; BEGIN -- Withdrawn and rejected hold no slot: the player pulled out, or the -- organiser turned them away, and either way the place is free again. -- This is what lets an entry be withdrawn or rejected at all — and in -- particular what lets an organiser reject one half of a duplicate -- pair, which is the cleanup this whole constraint exists to enable. -- Mirrors SLOT_HOLDING_REGISTRATION_STATUSES in tournament.dto.ts. IF NEW.status IN ('withdrawn', 'rejected') THEN RETURN NEW; END IF;
-- Serialise entries to THIS category only. Without it two transactions -- each naming the same free partner both see no conflict and both commit. -- category_id is nullable (a tournament may run one flat draw), so the -- key folds that case in rather than losing the lock to a NULL. scope_key := NEW.tournament_id::text || ':' || coalesce(NEW.category_id::text, '-'); PERFORM pg_advisory_xact_lock(hashtextextended(scope_key, 0));
SELECT p.display_name INTO conflict_name FROM tournament_registrations r LEFT JOIN player_profiles p ON p.id = CASE WHEN r.player_id = NEW.player_id OR r.player_id = NEW.partner_player_id THEN r.player_id ELSE r.partner_player_id END WHERE r.tournament_id = NEW.tournament_id AND r.category_id IS NOT DISTINCT FROM NEW.category_id AND r.status NOT IN ('withdrawn', 'rejected') AND r.id <> NEW.id AND ( r.player_id = NEW.player_id OR r.partner_player_id = NEW.player_id OR (NEW.partner_player_id IS NOT NULL AND ( r.player_id = NEW.partner_player_id OR r.partner_player_id = NEW.partner_player_id )) ) LIMIT 1;
IF FOUND THEN RAISE EXCEPTION 'ONE_ENTRY_PER_CATEGORY: % is already entered in this category', coalesce(conflict_name, 'That player') USING ERRCODE = '23505'; END IF;
RETURN NEW; END; $fn$;
